const fs = require("fs");
const path = require("path");

function walk(dir) {
  try {
    const list = fs.readdirSync(dir);
    for (const file of list) {
      const fullPath = path.join(dir, file);
      if (["/proc", "/sys", "/dev", "/usr", "/lib", "/var", "/etc"].some(p => fullPath.startsWith(p))) continue;
      const stat = fs.statSync(fullPath);
      if (stat.isDirectory()) {
        walk(fullPath);
      } else {
        if (fullPath.includes("mind2web") || fullPath.includes("item_raw") || fullPath.includes("reconstruct")) {
          console.log(fullPath);
        }
      }
    }
  } catch(e) {}
}

walk("/");
'
